const page = `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meridian Reserve Decision Desk</title><style>body{margin:0;background:#07111f;color:#edf4ff;font:16px Arial}main{max-width:1050px;margin:auto;padding:38px 20px}.card{background:#10213b;border:1px solid #285078;border-radius:12px;padding:16px;margin:15px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.pass{color:#6ee7b7}.fail{color:#fca5a5}canvas{width:100%;background:#09172a;border-radius:8px}input,button{padding:10px;border-radius:6px;border:0}button{background:#38bdf8;font-weight:bold}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style><main><p>Interactive Project 2 public dashboard</p><h1>Meridian Reserve Decision Desk</h1><p>Educational analysis only, not investment advice. Informational ticker data never enters the portfolio optimizer.</p><div class="grid"><section class="card"><b>Equal weight</b><p class="fail">FAIL - return objective</p><p>4.52% return<br>8.18% volatility</p></section><section class="card"><b>60/40 VTI/LQD</b><p class="fail">FAIL - reserve minimum</p><p>7.15% return<br>0% reserve</p></section><section class="card"><b>Constrained portfolio</b><p class="pass">PASS</p><p>65% BIL, 30% VTI, 5% XLV<br>6.56% return</p></section></div><section class="card"><h2>Stock ticker explorer</h2><input id="ticker" value="LLY" maxlength="12"><button onclick="load()">Load six month chart</button><p id="status">Type a ticker, then load it.</p><canvas id="stock" width="900" height="250"></canvas></section><div class="grid"><section class="card"><h2>DGS10</h2><p>10-year Treasury yield, preserved Lab 17 ALFRED context.</p><canvas id="dgs" width="450" height="210"></canvas></section><section class="card"><h2>FEDFUNDS</h2><p>Effective federal funds rate, preserved Lab 17 ALFRED context.</p><canvas id="fed" width="450" height="210"></canvas></section></div><p>Point-in-time rule: rates and LLY are context signals only. The optimizer uses its saved ETF monthly adjusted-close data and the stated mandate rules.</p></main><script>function draw(id,a,color='#38bdf8'){let c=document.getElementById(id),x=c.getContext('2d'),w=c.width,h=c.height,m=Math.min(...a),M=Math.max(...a),d=M-m||1;x.clearRect(0,0,w,h);x.strokeStyle=color;x.lineWidth=3;x.beginPath();a.forEach((v,i)=>{let X=15+i*(w-30)/(a.length-1),Y=h-20-(v-m)*(h-40)/d;i?x.lineTo(X,Y):x.moveTo(X,Y)});x.stroke();x.fillStyle='#b5cbe6';x.fillText(m.toFixed(2),15,h-5);x.fillText(M.toFixed(2),15,15)}let d=[4.26,4.3,4.36,4.42,4.45,4.59,4.67,4.5,4.49,4.55,4.45,4.51,4.48,4.56,4.62,4.55,4.63,4.71,4.75,4.68,4.72,4.69,4.75,4.8,4.96,5,4.94,4.96,5.18,5.24,5.28],f=[.4,.9,1.15,1.7,2.2,2.4,2.04,.65,.09,.08,.2,.77,1.68,2.56,3.78,4.33,4.83,5.12,5.33,5.13,4.64,4.33,4.22,3.88,3.64,3.63,3.75];draw('dgs',d);draw('fed',f,'#f59e0b');async function load(){let t=document.getElementById('ticker').value.trim().toUpperCase();let s=document.getElementById('status');s.textContent='Loading '+t+'...';try{let r=await fetch('/api/quote?t='+encodeURIComponent(t)),j=await r.json();if(!r.ok)throw Error(j.error||'lookup failed');draw('stock',j.closes,'#6ee7b7');s.textContent=j.ticker+' latest returned close: $'+j.closes[j.closes.length-1].toFixed(2)+' | '+j.closes.length+' observations'}catch(e){s.textContent='Ticker lookup unavailable: '+e.message}}</script>`;
export default {async fetch(request){const url=new URL(request.url);if(url.pathname==='/api/quote'){const ticker=(url.searchParams.get('t')||'').toUpperCase();if(!/^[A-Z0-9.-]{1,12}$/.test(ticker))return Response.json({error:'Invalid ticker'},{status:400});try{const upstream=await fetch('https://query1.finance.yahoo.com/v8/finance/chart/'+encodeURIComponent(ticker)+'?range=6mo&interval=1d',{headers:{'User-Agent':'Mozilla/5.0'}});const data=await upstream.json();const result=data.chart?.result?.[0];const closes=result?.indicators?.quote?.[0]?.close?.filter(x=>x!=null);if(!closes?.length)throw Error('No usable closes returned');return Response.json({ticker,closes},{headers:{'Cache-Control':'public, max-age=900'}})}catch(error){return Response.json({error:'Market source unavailable'},{status:502})}}return new Response(page,{headers:{'content-type':'text/html;charset=UTF-8'}})}};
